{
  "states": [
    "OpenConfirm",
    "OpenSent",
    "Established",
    "Idle",
    "Connect",
    "Active"
  ],
  "transitions": [
    {
      "from": "OpenConfirm",
      "event": "receipt of OPEN message with colliding BGP Identifier where local BGP Identifier is less than remote BGP Identifier",
      "action": "close the existing BGP connection and accept the new BGP connection initiated by the remote system",
      "to": "Established"
    },
    {
      "from": "OpenConfirm",
      "event": "receipt of OPEN message with colliding BGP Identifier where local BGP Identifier is greater than or equal to remote BGP Identifier",
      "action": "close the newly created BGP connection and continue using the existing one",
      "to": "OpenConfirm"
    },
    {
      "from": "Established",
      "event": "connection collision with an existing BGP connection",
      "action": "close the newly created connection",
      "to": "Established"
    }
  ]
}

